create table depositos (deposito_id int primary key, nombre text not null, zona text not null);
insert into depositos
select g, 'Depósito ' || g, (array['Norte','Sur','Oeste','Centro'])[1 + g % 4] from generate_series(1,12) g;

create table clientes (cliente_id int primary key, nombre text not null);
insert into clientes select g, 'Cliente ' || lpad(g::text, 3, '0') from generate_series(1, 211) g;

create table bultos (
  bulto_id    int primary key,
  cliente_id  int not null,
  deposito_id int not null references depositos,
  fecha_alta  timestamptz not null,
  estado      text not null,
  peso_g      int not null
);

insert into bultos
select i,
       1 + (i * 7919::bigint) % 211,
       1 + (i * 31) % 12,
       timestamptz '2026-01-01 00:00+00' + ((i * 7919::bigint) % 26784000) * interval '1 second',
       case when i % 100 < 85 then 'entregado'
            when i % 100 < 95 then 'en_ruta'
            when i % 100 < 99 then 'pendiente'
            else 'demorado' end,
       200 + (i * 37) % 24000
from generate_series(1, 1000000) i;

vacuum analyze;

select b.bulto_id, b.fecha_alta, d.nombre
from bultos b join depositos d using (deposito_id)
where b.cliente_id = 77 and b.estado = 'demorado'
order by b.fecha_alta desc limit 20;

create table novedades (
  novedad_id int primary key,
  cliente_id int not null,
  estado     text not null
) with (autovacuum_enabled = false);          -- solo para que la demo no dependa del reloj
create index novedades_estado_idx on novedades (estado);

insert into novedades
select i, 1 + (i * 7919::bigint) % 211, 'pendiente' from generate_series(1, 100000) i;
analyze novedades;

-- carga masiva: 300.000 filas con un estado que la tabla nunca tuvo
insert into novedades
select 100000 + i, 1 + (i * 7919::bigint) % 211, 'demorado' from generate_series(1, 300000) i;
